WITH s AS (
  SELECT p.category, p.name, SUM(oi.quantity) AS qty
  FROM order_items oi
  JOIN products p ON p.id = oi.product_id
  GROUP BY p.category, p.name
), r AS (
  SELECT *, ROW_NUMBER() OVER (PARTITION BY category ORDER BY qty DESC, name) AS rn
  FROM s
)
SELECT category, name, qty FROM r WHERE rn = 1 ORDER BY qty DESC;

